import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Executor Directory","description":"Positioning, boundaries, and acceptance criteria for Codex, Native, Connector, Browser, GUI, and Document/Data executors.","frontmatter":{"title":"Executor Directory","description":"Positioning, boundaries, and acceptance criteria for Codex, Native, Connector, Browser, GUI, and Document/Data executors.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/executor-catalog.md","filePath":"en/architecture/executor-catalog.md","lastUpdated":null}'),n={name:"en/architecture/executor-catalog.md"};function r(l,e,s,c,d,u){return i(),t("div",null,[...e[0]||(e[0]=[o(`<p class="eyebrow">EXECUTOR CATALOG</p><h1 id="executor-catalog" tabindex="-1">Executor Catalog <a class="header-anchor" href="#executor-catalog" aria-label="Permalink to &quot;Executor Catalog&quot;">​</a></h1><p class="lead">What Codex, Native, Connector, Browser, GUI, and Document/Data are each good at, when they get selected, and how they are verified and taken over.</p><h2 id="codex-executor" tabindex="-1">Codex Executor <a class="header-anchor" href="#codex-executor" aria-label="Permalink to &quot;Codex Executor&quot;">​</a></h2><h3 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to &quot;Positioning&quot;">​</a></h3><p>Codex is not limited to code; it can take on research, long documents, reports, spreadsheets, code, and multi-file workspace tasks. But it is an Executor, not Hearth&#39;s permission center, task database, memory center, or external side-effect gateway.</p><p>Suited for:</p><ul><li>Long-chain reasoning in an isolated workspace;</li><li>Code changes, testing, Issue triage, PR preparation;</li><li>Research, summarization, and structured investigation;</li><li>Document, report, spreadsheet, and data file generation/modification;</li><li>Multi-step Shell, file conversion, and verification.</li></ul><p>Not suited for:</p><ul><li>Directly managing email, calendars, and contacts;</li><li>Serving as long-term memory;</li><li>Serving as a permission, approval, or credential center;</li><li>Resident event listening;</li><li>Real-time desktop and mobile operation;</li><li>Directly sending and publishing high-risk side effects.</li></ul><h3 id="task-pack-and-output-contract" tabindex="-1">Task Pack and Output Contract <a class="header-anchor" href="#task-pack-and-output-contract" aria-label="Permalink to &quot;Task Pack and Output Contract&quot;">​</a></h3><p>Do not give Codex an unbounded long prompt. The input should be a Task Pack:</p><ul><li>Goal, acceptance criteria, and prohibitions;</li><li>Minimal necessary files, references, and artifact paths;</li><li>Workspace scope, writable directories, and network boundaries;</li><li>Available tools, budget, deadline, and cancellation semantics;</li><li>Required structured output schema;</li><li>Known failure samples and degradation approach.</li></ul><p>The output must include at least: a standardized event stream, artifact references, a structured final result, verification results, failure classification, and recoverability. A natural-language &quot;done&quot; does not count as done.</p><h3 id="isolation-cancellation-and-recovery" tabindex="-1">Isolation, Cancellation, and Recovery <a class="header-anchor" href="#isolation-cancellation-and-recovery" aria-label="Permalink to &quot;Isolation, Cancellation, and Recovery&quot;">​</a></h3><ul><li>One workspace per Run, reclaimed when the task ends;</li><li>Version-locked CLI/SDK; run contract tests before upgrading;</li><li>Minimal environment variables and network egress;</li><li>Cancellation must terminate the entire process tree;</li><li>Timeouts, crashes, and recovery must preserve checkpoints or a rebuildable workspace;</li><li>High-risk accounts and long-lived credentials are not handed directly to Codex.</li></ul><h3 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h3><ul><li>The Task Pack is reproducible;</li><li>Structured results are parseable;</li><li>Artifacts have diffs, tests, references, or file evidence;</li><li>Cancellation, timeout, and failure classification are available;</li><li>Tokens and cost are attributable;</li><li>No reliance on a natural-language &quot;done&quot;.</li></ul><h2 id="native-runtime" tabindex="-1">Native Runtime <a class="header-anchor" href="#native-runtime" aria-label="Permalink to &quot;Native Runtime&quot;">​</a></h2><p>Native is a lightweight, local, replaceable general-purpose reasoning layer, suited for short tasks, low-risk classification, context compression, and some privacy-sensitive work. It does not aim to replace Codex&#39;s long-chain capabilities.</p><h3 id="model-ladder" tabindex="-1">Model Ladder <a class="header-anchor" href="#model-ladder" aria-label="Permalink to &quot;Model Ladder&quot;">​</a></h3><ul><li>Rules/scripts: no model at all;</li><li>Small/local models: classification, extraction, short summaries;</li><li>Mid-sized models: general reasoning, structured organization;</li><li>Codex/large models: long-chain, multi-file, high-value tasks.</li></ul><h3 id="tool-interface-and-escalation" tabindex="-1">Tool Interface and Escalation <a class="header-anchor" href="#tool-interface-and-escalation" aria-label="Permalink to &quot;Tool Interface and Escalation&quot;">​</a></h3><p>Native reads and writes files, executes commands, and calls Connectors only through a controlled tool interface. Escalate to Codex when:</p><ul><li>The task requires extensive file coordination;</li><li>Long-chain planning and repeated verification are needed;</li><li>Native fails repeatedly or the context exceeds budget;</li><li>Artifact quality or reliability falls short;</li><li>Stronger code/document handling capability is required.</li></ul><h3 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h3><p>Evaluation should not just look at whether &quot;the answer looks decent&quot;, but also at task success rate, human minutes, Tokens, tool-call correctness rate, failure classification, and escalation rate. A small model that &quot;saves money but fails repeatedly&quot; is usually more expensive.</p><h2 id="connector-executor" tabindex="-1">Connector Executor <a class="header-anchor" href="#connector-executor" aria-label="Permalink to &quot;Connector Executor&quot;">​</a></h2><p>Connectors turn external systems into auditable <code>Source</code> and <code>Effect</code>, not &quot;handing the API keys to the model&quot;.</p><h3 id="unified-model" tabindex="-1">Unified Model <a class="header-anchor" href="#unified-model" aria-label="Permalink to &quot;Unified Model&quot;">​</a></h3><ul><li>Source: read, sync, normalize, provenance, cursor, rate limiting;</li><li>Effect: typed actions, preview, approval, outbox, idempotency key, Receipt, reconciliation;</li><li>Credentials: the Credential Broker issues short-lived permissions; the Executor never sees long-lived keys;</li><li>Permissions: scoped by account, resource, action, time, and scope;</li><li>Failures: retryable, non-retryable, indeterminate, and requiring human takeover are handled separately.</li></ul><h3 id="email-calendar-documents-im" tabindex="-1">Email, Calendar, Documents, IM <a class="header-anchor" href="#email-calendar-documents-im" aria-label="Permalink to &quot;Email, Calendar, Documents, IM&quot;">​</a></h3><ul><li>Email: read-only sync, threads, contacts, attachments, drafts, sends pending approval;</li><li>Calendar: read-only, time zones, conflict checks, writes pending approval;</li><li>Documents/cloud drive: read, version, export, sharing pending approval;</li><li>IM/Issue/code hosting: messages, Issues, PRs, comments as Source/Effect, with approval for high-risk actions.</li></ul><p>In Stage 2, connect one real read-only Connector first, then gradually add writes. Do not enable all high-risk actions on the first Connector at once.</p><h3 id="rate-limiting-retries-and-reconciliation" tabindex="-1">Rate Limiting, Retries, and Reconciliation <a class="header-anchor" href="#rate-limiting-retries-and-reconciliation" aria-label="Permalink to &quot;Rate Limiting, Retries, and Reconciliation&quot;">​</a></h3><ul><li>Every delivery has an idempotency key;</li><li>Rate limiting and backoff are controlled by the system, not left to the model to retry freely;</li><li>Indeterminate results are queried/reconciled first;</li><li>Dead letters can be inspected, fixed, and manually replayed;</li><li>Revocation and permission reclamation must be audited.</li></ul><h2 id="browser-executor" tabindex="-1">Browser Executor <a class="header-anchor" href="#browser-executor" aria-label="Permalink to &quot;Browser Executor&quot;">​</a></h2><p>Browser uses Playwright to operate web pages that have no API or an insufficient API, but web page content is untrusted input.</p><h3 id="three-modes" tabindex="-1">Three Modes <a class="header-anchor" href="#three-modes" aria-label="Permalink to &quot;Three Modes&quot;">​</a></h3><ol><li><strong>Read-only research</strong>: open, restricted login state, capture, screenshots, provenance;</li><li><strong>Draft operations</strong>: fill forms, prepare submission but do not auto-send;</li><li><strong>Controlled execution</strong>: submit low/medium-risk actions under a Mandate and approval.</li></ol><h3 id="execution-flow" tabindex="-1">Execution Flow <a class="header-anchor" href="#execution-flow" aria-label="Permalink to &quot;Execution Flow&quot;">​</a></h3><ul><li>Clarify the goal and allowed domains;</li><li>Prepare an isolated profile;</li><li>Observe the page and provenance;</li><li>Auto-execute non-high-risk steps;</li><li>Take over on CAPTCHAs, anomalies, or high-risk submissions;</li><li>Save screenshots, DOM/state evidence, and provenance;</li><li>Verify the final state and produce a Receipt (if there are side effects).</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>Page text must not be treated as system instructions;</li><li>Prompt injection must not expand permissions;</li><li>Login state is isolated from long-lived credentials;</li><li>Network egress allowlist;</li><li>Downloaded files must have their type and provenance verified;</li><li>Untrusted pages must not directly trigger payments, publishing, deletion, or permission changes.</li></ul><h3 id="failures-and-takeover" tabindex="-1">Failures and Takeover <a class="header-anchor" href="#failures-and-takeover" aria-label="Permalink to &quot;Failures and Takeover&quot;">​</a></h3><p>Browser failures usually cannot be solved by &quot;try again&quot;. CAPTCHAs, MFA, page structure changes, expired logins, and irreversible submissions must explicitly enter <code>needs_human</code> and show the user what they need to do.</p><h2 id="gui-executor" tabindex="-1">GUI Executor <a class="header-anchor" href="#gui-executor" aria-label="Permalink to &quot;GUI Executor&quot;">​</a></h2><p>GUI operates desktop software without an API and cross-application workflows. It is more fragile than Browser, so it relies more on allowlists, verification, and takeover.</p><h3 id="runtime-location" tabindex="-1">Runtime Location <a class="header-anchor" href="#runtime-location" aria-label="Permalink to &quot;Runtime Location&quot;">​</a></h3><ul><li>The device <code>agentd</code> runs on the target desktop;</li><li>Uses the accessibility tree, screenshots, keyboard/mouse, windows, and file selection;</li><li>High-risk tasks run on an isolated virtual desktop;</li><li>Mobile is only a view/takeover entry point, not the default execution authority.</li></ul><h3 id="execution-flow-1" tabindex="-1">Execution Flow <a class="header-anchor" href="#execution-flow-1" aria-label="Permalink to &quot;Execution Flow&quot;">​</a></h3><ol><li>Identify the target application and window;</li><li>Confirm capabilities and permissions;</li><li>Observe the current state;</li><li>Perform the minimal action;</li><li>Verify via the accessibility tree, screenshots, or target state;</li><li>On failure, pause, take over, or roll back;</li><li>Record audit and evidence.</li></ol><h3 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h3><ul><li>Application/window allowlist;</li><li>Do not read password vaults;</li><li>Do not modify system security settings;</li><li>Secondary confirmation for high-risk actions;</li><li>Do not assume screen coordinates are always stable;</li><li>Verify state after each operation, not just &quot;the click succeeded&quot;.</li></ul><h3 id="failures-and-takeover-1" tabindex="-1">Failures and Takeover <a class="header-anchor" href="#failures-and-takeover-1" aria-label="Permalink to &quot;Failures and Takeover&quot;">​</a></h3><p>GUI must assume it will fail. Users must be able to pause automated input, take over, operate, hand back, or terminate; the system must record the state before and after takeover to avoid automated flows and humans fighting over keyboard and mouse at the same time.</p><h2 id="document-data-executor" tabindex="-1">Document/Data Executor <a class="header-anchor" href="#document-data-executor" aria-label="Permalink to &quot;Document/Data Executor&quot;">​</a></h2><p>Document/Data lets deterministic work bypass the model: parsing, OCR, format conversion, spreadsheet cleansing, reconciliation, statistics, charts, and import/export.</p><h3 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Input file → Type detection → Parsing/OCR → Structured intermediate result</span></span>
<span class="line"><span>→ Deterministic transformation/computation → Validation → Artifact + Provenance</span></span></code></pre></div><p>The model only handles the parts that truly require semantic judgment; repeated calculations, format conversions, and data validation do not invoke the model.</p><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><ul><li>Document structure, page numbers, citations, and key fields;</li><li>Table schema, row counts, formulas, sampling, and reconciliation;</li><li>Output is reproducible, diffable, and traceable back to the original file;</li><li>For large files, only the required fragments and Artifact references are extracted;</li><li>The original file is not destroyed, and failures can be rolled back.</li></ul><h3 id="division-of-labor-with-codex" tabindex="-1">Division of Labor with Codex <a class="header-anchor" href="#division-of-labor-with-codex" aria-label="Permalink to &quot;Division of Labor with Codex&quot;">​</a></h3><ul><li>Deterministic processing: Document/Data;</li><li>Long document understanding, writing, complex formatting, and multi-file coordination: Codex;</li><li>Routing decides which is cheaper and more reliable, not tool preference.</li></ul>`,65)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
